44| *
45| * @template T
46| * @param arr - The array to search through.
47| * @param doesMatch - The predicate function, partial object, property-value pair, or property name.
48| * @param [fromIndex=arr.length - 1] - The index to start the search from, defaults to the last index of the array.
49| * @returns The index of the last matching element, or -1 if not found.
50| *
51| * @example
52| * const items = [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }];
53| * findLastIndex(items, 'name');
54| * // => 1
55| */
56|export function findLastIndex<T>(
57|  arr: ArrayLike<T> | null | undefined,
58|  doesMatch: ((item: T, index: number, arr: any) => unknown) | Partial<T> | [keyof T, unknown] | PropertyKey = identity,
59|  fromIndex: number = arr ? arr.length - 1 : 0
