14| * @returns The index of the first item that has the specified property, or `-1` if no match is found.
15| *
16| * @example
17| * // Using a property name
18| * const items = [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }];
19| * const result = findIndex(items, 'name');
20| * console.log(result); // 0
21| */
22|export function findIndex<T>(
23|  arr: ArrayLike<T> | null | undefined,
24|  doesMatch: ListIterateeCustom<T, boolean> = identity,
25|  fromIndex = 0
26|): number {
27|  if (!arr) {
28|    return -1;
29|  }
30|  if (Number.isNaN(fromIndex)) {
31|    fromIndex = 0;
32|  }
33|  if (fromIndex < 0) {
34|    fromIndex = Math.max(arr.length + fromIndex, 0);
35|  }
36|  const subArray = Array.from(arr).slice(fromIndex);
37|  let index = -1;
38|  switch (typeof doesMatch) {
39|    case 'function': {
40|      index = subArray.findIndex(doesMatch);
41|      break;
42|    }
43|    case 'object': {
44|      if (Array.isArray(doesMatch) && doesMatch.length === 2) {
45|        const key = doesMatch[0];
46|        const value = doesMatch[1];
