50|        index = subArray.findIndex(matches(doesMatch));
51|      }
52|      break;
53|    }
54|    case 'number':
55|    case 'symbol':
56|    case 'string': {
57|      index = subArray.findIndex(property(doesMatch));
58|    }
59|  }
60|  return index === -1 ? -1 : index + fromIndex;
61|}

